<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { useRoute, useRouter } from 'vue-router'
import { Download, Edit3, ExternalLink, Plus, RefreshCw, Trash2, Upload } from '@lucide/vue'
import AppPage from '../../components/ui/AppPage.vue'
import PageHeader from '../../components/ui/PageHeader.vue'
import AppToolbar from '../../components/ui/AppToolbar.vue'
import AppFilterBar from '../../components/ui/AppFilterBar.vue'
import AppTable from '../../components/ui/AppTable.vue'
import AppCard from '../../components/ui/AppCard.vue'
import AppEmptyState from '../../components/ui/AppEmptyState.vue'
import AppLoading from '../../components/ui/AppLoading.vue'
import AppErrorBanner from '../../components/ui/AppErrorBanner.vue'
import AppStatusBadge from '../../components/ui/AppStatusBadge.vue'
import AppConfirmDialog from '../../components/ui/AppConfirmDialog.vue'
import PersonPhotoManager from '../../components/person/PersonPhotoManager.vue'
import { TABLE_ROWS_PER_PAGE_OPTIONS, createTablePagination, persistTablePagination } from '../../services/tableSettings'
import { useReferenceOptionsStore } from '../../stores/referenceOptions'
import { GRADUATE_STATUS_OPTIONS, formatRuDate, statusLabel, statusTone, studentName, useGraduationStore } from '../../stores/graduation'

const store = useGraduationStore()
const referenceOptions = useReferenceOptionsStore()
const $q = useQuasar(), route = useRoute(), router = useRouter()
const rowsKey = 'collegePortal.graduation.rowsPerPage'
const syncingQuery = ref(false), formVisible = ref(false), diplomaVisible = ref(false), supplementVisible = ref(false), deleteDialogVisible = ref(false), importFile = ref(null)
const editingGraduate = ref(null), deletingGraduate = ref(null), tab = ref('general')
const tablePagination = ref(createTablePagination(rowsKey, { sortBy: 'graduation_year', descending: true, rowsPerPage: 20 }))
const graduateForm = reactive({ student_id: '', group_id: '', education_program_id: '', specialty_id: '', graduation_year: new Date().getFullYear(), qualification: '', status: 'draft', note: '' })
const diplomaForm = reactive({ series: '', number: '', registration_number: '', issue_date: '', qualification: '', gia_decision: '', status: 'draft', note: '' })
const supplementForm = reactive({ series: '', number: '', issue_date: '', status: 'draft', note: '' })
const columns = [
  { name: 'student', label: 'Выпускник', field: 'student', align: 'left', sortable: true },
  { name: 'group', label: 'Группа', field: 'group', align: 'left', sortable: true },
  { name: 'program', label: 'Программа', field: 'education_program', align: 'left' },
  { name: 'year', label: 'Год', field: 'graduation_year', align: 'left', sortable: true },
  { name: 'diploma', label: 'Диплом', field: 'diploma', align: 'left' },
  { name: 'status', label: 'Статус', field: 'status', align: 'left' },
  { name: 'actions', label: '', field: 'actions', align: 'right' },
]
const diplomaStatusOptions = computed(() => referenceOptions.options('diploma_statuses'))
function diplomaStatusLabel(value) { return referenceOptions.label('diploma_statuses', value, value || '—') }
function diplomaStatusTone(value) { return referenceOptions.tone('diploma_statuses', value, 'neutral') }
const tableSubtitle = computed(() => `Найдено выпускников: ${store.filteredGraduates.length}`)
const selected = computed(() => store.selectedGraduate)
const diploma = computed(() => selected.value?.diploma || null)
const supplement = computed(() => diploma.value?.supplement || null)
const studentRoute = computed(() => ({ path: '/students', query: { selected: selected.value?.student_id } }))
const groupRoute = computed(() => ({ path: '/groups', query: { selected: selected.value?.group_id } }))
const examsRoute = computed(() => ({ path: '/exams', query: { group: selected.value?.group_id } }))
const frdoRoute = computed(() => ({ path: '/reports', query: { scope: 'frdo', graduate: selected.value?.id } }))
function notify(message) { $q.notify({ type: 'positive', message, position: 'top-right', timeout: 1800 }) }
function updatePhoto(payload) { if (selected.value) { selected.value.photo_url = payload.photo_url; selected.value.photo_path = payload.photo_path } }
function removePhoto() { if (selected.value) { selected.value.photo_url = null; selected.value.photo_path = null } }
function rowClass(row) { return Number(row.id) === Number(store.selectedId) ? 'graduation-row--selected' : '' }
function updatePagination(p) { tablePagination.value = p; persistTablePagination(rowsKey, p) }
function routeSelectedId() { return route.query.selected ? String(route.query.selected) : '' }
async function syncQuery(selectedId = routeSelectedId()) { const query = { ...route.query }; selectedId ? query.selected = selectedId : delete query.selected; syncingQuery.value = true; await router.replace({ path: '/graduation', query }); syncingQuery.value = false }
async function selectGraduate(graduate) { store.select(graduate); tab.value = 'general'; await syncQuery(graduate?.id || '') }
function programName(graduate) { return graduate?.education_program?.name || '—' }
function specialtyName(graduate) { return [graduate?.specialty?.code, graduate?.specialty?.name].filter(Boolean).join(' · ') || '—' }
function openCreateForm() { editingGraduate.value = null; Object.assign(graduateForm, { student_id: '', group_id: '', education_program_id: '', specialty_id: '', graduation_year: new Date().getFullYear(), qualification: '', status: 'draft', note: '' }); formVisible.value = true }
function openEditForm(graduate) { editingGraduate.value = graduate; Object.assign(graduateForm, { student_id: graduate.student_id, group_id: graduate.group_id || '', education_program_id: graduate.education_program_id || '', specialty_id: graduate.specialty_id || '', graduation_year: graduate.graduation_year, qualification: graduate.qualification || '', status: graduate.status || 'draft', note: graduate.note || '' }); formVisible.value = true }
async function saveGraduate() { const isEdit = Boolean(editingGraduate.value?.id); await store.save(graduateForm, editingGraduate.value?.id || null); formVisible.value = false; notify(isEdit ? 'Выпускник обновлен' : 'Выпускник создан') }
function openDiplomaForm() { Object.assign(diplomaForm, { series: diploma.value?.series || '', number: diploma.value?.number || '', registration_number: diploma.value?.registration_number || '', issue_date: diploma.value?.issue_date || '', qualification: diploma.value?.qualification || selected.value?.qualification || '', gia_decision: diploma.value?.gia_decision || '', status: diploma.value?.status || 'draft', note: diploma.value?.note || '' }); diplomaVisible.value = true }
async function saveDiploma() { await store.saveDiploma(diplomaForm); diplomaVisible.value = false; notify('Диплом сохранен') }
function openSupplementForm() { Object.assign(supplementForm, { series: supplement.value?.series || '', number: supplement.value?.number || '', issue_date: supplement.value?.issue_date || '', status: supplement.value?.status || 'draft', note: supplement.value?.note || '' }); supplementVisible.value = true }
async function saveSupplement() { await store.saveSupplement(supplementForm); supplementVisible.value = false; notify('Приложение сохранено') }
function requestDelete(graduate) { deletingGraduate.value = graduate; deleteDialogVisible.value = true }
async function confirmDelete() { await store.remove(deletingGraduate.value); deletingGraduate.value = null; notify('Выпускник удален') }
async function applyFilters() { store.setFilters({ ...store.filters }); await syncQuery('') }
async function resetFilters() { store.resetFilters(); await syncQuery('') }
async function handleImport(file) { if (!file) return; await store.importCsv(file); importFile.value = null; notify('Импорт выпускников завершен') }
async function exportCsv() { await store.exportCsv(); notify('Экспорт выпускников подготовлен') }
watch(() => route.query.selected, () => { if (!syncingQuery.value) store.selectById(routeSelectedId()) })
onMounted(async () => { await referenceOptions.loadCatalog('diploma_statuses'); store.selectById(routeSelectedId()); await store.load(); if (!store.selectedGraduate && store.filteredGraduates[0]) await selectGraduate(store.filteredGraduates[0]) })
</script>

<template>
  <AppPage>
    <PageHeader title="Выпускники и дипломы" subtitle="Выпускники, дипломы, приложения и подготовка данных к ФРДО."><template #actions><q-btn color="primary" @click="openCreateForm"><Plus :size="16" class="q-mr-xs" /> Создать из студента</q-btn></template></PageHeader>
    <AppToolbar><span>{{ tableSubtitle }}</span><template #actions><AppLoading v-if="store.loading" label="Загрузка выпускников..." /><q-btn flat :disable="store.loading" @click="store.load"><RefreshCw :size="16" class="q-mr-xs" /> Обновить</q-btn><q-file v-model="importFile" dense outlined accept=".csv,text/csv" label="Импорт" style="max-width: 180px" @update:model-value="handleImport"><template #prepend><Upload :size="16" /></template></q-file><q-btn color="primary" @click="exportCsv"><Download :size="16" class="q-mr-xs" /> Экспорт</q-btn></template></AppToolbar>
    <AppErrorBanner :message="store.error" />
    <AppFilterBar><q-select v-model="store.filters.graduation_year" dense outlined clearable emit-value map-options label="Год выпуска" :options="store.graduationYearOptions" /><q-select v-model="store.filters.group_id" dense outlined clearable emit-value map-options label="Группа" :options="store.groupOptions" /><q-select v-model="store.filters.education_program_id" dense outlined clearable emit-value map-options label="Программа" :options="store.programOptions" /><q-select v-model="store.filters.diploma_status" dense outlined clearable emit-value map-options label="Статус диплома" :options="diplomaStatusOptions" /><template #actions><q-btn color="primary" @click="applyFilters">Применить</q-btn><q-btn flat @click="resetFilters">Сбросить</q-btn></template></AppFilterBar>
    <div class="graduation-workspace"><div class="graduation-main"><AppTable v-if="store.filteredGraduates.length || store.loading" :rows="store.filteredGraduates" :columns="columns" :loading="store.loading" :pagination="tablePagination" :rows-per-page-options="TABLE_ROWS_PER_PAGE_OPTIONS" :table-row-class-fn="rowClass" @update:pagination="updatePagination" @row-click="(_, row) => selectGraduate(row)"><template #body-cell-student="props"><q-td :props="props"><button class="graduation-row-link" type="button" @click.stop="selectGraduate(props.row)">{{ studentName(props.row.student) }}</button><div class="graduation-secondary-cell">{{ props.row.qualification || 'Квалификация не указана' }}</div></q-td></template><template #body-cell-group="props"><q-td :props="props">{{ props.row.group?.name || '—' }}</q-td></template><template #body-cell-program="props"><q-td :props="props"><div class="graduation-strong-cell">{{ programName(props.row) }}</div><div class="graduation-secondary-cell">{{ specialtyName(props.row) }}</div></q-td></template><template #body-cell-year="props"><q-td :props="props">{{ props.row.graduation_year }}</q-td></template><template #body-cell-diploma="props"><q-td :props="props"><AppStatusBadge :label="diplomaStatusLabel(props.row.diploma?.status || 'draft')" :tone="diplomaStatusTone(props.row.diploma?.status || 'draft')" /></q-td></template><template #body-cell-status="props"><q-td :props="props"><AppStatusBadge :label="statusLabel(GRADUATE_STATUS_OPTIONS, props.row.status)" :tone="statusTone(GRADUATE_STATUS_OPTIONS, props.row.status)" /></q-td></template><template #body-cell-actions="props"><q-td :props="props"><q-btn flat round dense title="Редактировать" @click.stop="openEditForm(props.row)"><Edit3 :size="16" /></q-btn><q-btn flat round dense color="negative" title="Удалить" @click.stop="requestDelete(props.row)"><Trash2 :size="16" /></q-btn></q-td></template></AppTable><AppEmptyState v-else title="Выпускники не найдены" description="Создайте выпускника из студента или импортируйте CSV." /></div>
      <aside class="graduation-side"><AppCard class="graduation-card"><AppEmptyState v-if="!selected" title="Выпускник не выбран" description="Выберите строку в таблице, чтобы открыть карточку выпускника." /><div v-else class="graduation-details"><div class="graduation-details__hero graduation-details__hero--with-photo"><PersonPhotoManager type="graduates" :person="selected" compact @updated="updatePhoto" @removed="removePhoto" /><div class="graduation-details__hero-text"><h2>{{ studentName(selected.student) }}</h2><div><AppStatusBadge :label="statusLabel(GRADUATE_STATUS_OPTIONS, selected.status)" :tone="statusTone(GRADUATE_STATUS_OPTIONS, selected.status)" /><AppStatusBadge :label="diplomaStatusLabel(diploma?.status || 'draft')" :tone="diplomaStatusTone(diploma?.status || 'draft')" class="q-ml-xs" /></div><p>{{ selected.group?.name || 'Группа не указана' }} · выпуск {{ selected.graduation_year }}</p></div></div><div class="graduation-details__metrics"><div><span>Год</span><strong>{{ selected.graduation_year }}</strong></div><div><span>Диплом</span><strong>{{ diploma?.number || '—' }}</strong></div><div><span>Приложение</span><strong>{{ supplement?.number || '—' }}</strong></div></div><q-tabs v-model="tab" dense align="left" class="graduation-tabs"><q-tab name="general" label="Общие" /><q-tab name="diploma" label="Диплом" /><q-tab name="supplement" label="Приложение" /><q-tab name="history" label="История" /></q-tabs><q-tab-panels v-model="tab" animated class="graduation-panels"><q-tab-panel name="general"><section><h3>Общие сведения</h3><dl class="graduation-fields"><div><dt>Программа</dt><dd>{{ programName(selected) }}</dd></div><div><dt>Специальность</dt><dd>{{ specialtyName(selected) }}</dd></div><div><dt>Квалификация</dt><dd>{{ selected.qualification || 'Не указана' }}</dd></div><div><dt>Комментарий</dt><dd>{{ selected.note || '—' }}</dd></div></dl><div class="graduation-actions"><q-btn flat no-caps class="entity-link-action" :to="studentRoute"><ExternalLink :size="15" class="q-mr-xs" /> Открыть студента</q-btn><q-btn flat no-caps class="entity-link-action" :to="groupRoute"><ExternalLink :size="15" class="q-mr-xs" /> Открыть группу</q-btn><q-btn flat no-caps class="entity-link-action" :to="examsRoute"><ExternalLink :size="15" class="q-mr-xs" /> Открыть экзамены/ГИА</q-btn><q-btn flat no-caps class="entity-link-action" :to="frdoRoute"><ExternalLink :size="15" class="q-mr-xs" /> Подготовить к ФРДО</q-btn></div></section></q-tab-panel><q-tab-panel name="diploma"><section><div class="graduation-section-header"><h3>Диплом</h3><q-btn dense color="primary" @click="openDiplomaForm"><Edit3 :size="15" class="q-mr-xs" /> Сохранить диплом</q-btn></div><dl class="graduation-fields"><div><dt>Серия и номер</dt><dd>{{ [diploma?.series, diploma?.number].filter(Boolean).join(' ') || '—' }}</dd></div><div><dt>Регистрационный номер</dt><dd>{{ diploma?.registration_number || '—' }}</dd></div><div><dt>Дата выдачи</dt><dd>{{ formatRuDate(diploma?.issue_date) }}</dd></div><div><dt>Решение ГИА</dt><dd>{{ diploma?.gia_decision || '—' }}</dd></div></dl></section></q-tab-panel><q-tab-panel name="supplement"><section><div class="graduation-section-header"><h3>Приложение</h3><q-btn dense color="primary" @click="openSupplementForm"><Edit3 :size="15" class="q-mr-xs" /> Сохранить приложение</q-btn></div><dl class="graduation-fields"><div><dt>Серия и номер</dt><dd>{{ [supplement?.series, supplement?.number].filter(Boolean).join(' ') || '—' }}</dd></div><div><dt>Дата выдачи</dt><dd>{{ formatRuDate(supplement?.issue_date) }}</dd></div><div><dt>Статус</dt><dd>{{ diplomaStatusLabel(supplement?.status || 'draft') }}</dd></div><div><dt>Комментарий</dt><dd>{{ supplement?.note || '—' }}</dd></div></dl></section></q-tab-panel><q-tab-panel name="history"><section><h3>История</h3><p class="graduation-muted">История изменений будет подключена на следующем этапе.</p></section></q-tab-panel></q-tab-panels></div></AppCard></aside></div>
    <q-dialog v-model="formVisible"><q-card class="graduation-dialog"><q-card-section><div class="text-h6">{{ editingGraduate ? 'Редактировать выпускника' : 'Создать выпускника из студента' }}</div></q-card-section><q-card-section class="graduation-dialog__body"><q-select v-model="graduateForm.student_id" outlined dense emit-value map-options label="Студент" :options="store.studentOptions" :disable="Boolean(editingGraduate)" /><q-select v-model="graduateForm.group_id" outlined dense clearable emit-value map-options label="Группа" :options="store.groupOptions" /><q-select v-model="graduateForm.education_program_id" outlined dense clearable emit-value map-options label="Образовательная программа" :options="store.programOptions" /><q-select v-model="graduateForm.specialty_id" outlined dense clearable emit-value map-options label="Специальность" :options="store.specialtyOptions" /><q-input v-model="graduateForm.graduation_year" outlined dense type="number" label="Год выпуска" /><q-input v-model="graduateForm.qualification" outlined dense label="Квалификация" /><q-select v-model="graduateForm.status" outlined dense emit-value map-options label="Статус" :options="GRADUATE_STATUS_OPTIONS" /><q-input v-model="graduateForm.note" outlined dense type="textarea" label="Комментарий" /></q-card-section><q-card-actions align="right"><q-btn flat label="Отмена" @click="formVisible = false" /><q-btn color="primary" :loading="store.saving" :disable="!graduateForm.student_id || !graduateForm.graduation_year" @click="saveGraduate">Сохранить</q-btn></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="diplomaVisible"><q-card class="graduation-dialog"><q-card-section><div class="text-h6">Диплом</div></q-card-section><q-card-section class="graduation-dialog__body"><q-input v-model="diplomaForm.series" outlined dense label="Серия" /><q-input v-model="diplomaForm.number" outlined dense label="Номер" /><q-input v-model="diplomaForm.registration_number" outlined dense label="Регистрационный номер" /><q-input v-model="diplomaForm.issue_date" outlined dense type="date" label="Дата выдачи" /><q-input v-model="diplomaForm.qualification" outlined dense label="Квалификация" /><q-input v-model="diplomaForm.gia_decision" outlined dense label="Решение ГИА" /><q-select v-model="diplomaForm.status" outlined dense emit-value map-options label="Статус" :options="diplomaStatusOptions" /><q-input v-model="diplomaForm.note" outlined dense type="textarea" label="Комментарий" /></q-card-section><q-card-actions align="right"><q-btn flat label="Отмена" @click="diplomaVisible = false" /><q-btn color="primary" :loading="store.saving" @click="saveDiploma">Сохранить</q-btn></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="supplementVisible"><q-card class="graduation-dialog"><q-card-section><div class="text-h6">Приложение к диплому</div></q-card-section><q-card-section class="graduation-dialog__body"><q-input v-model="supplementForm.series" outlined dense label="Серия" /><q-input v-model="supplementForm.number" outlined dense label="Номер" /><q-input v-model="supplementForm.issue_date" outlined dense type="date" label="Дата выдачи" /><q-select v-model="supplementForm.status" outlined dense emit-value map-options label="Статус" :options="diplomaStatusOptions" /><q-input v-model="supplementForm.note" outlined dense type="textarea" label="Комментарий" /></q-card-section><q-card-actions align="right"><q-btn flat label="Отмена" @click="supplementVisible = false" /><q-btn color="primary" :loading="store.saving" @click="saveSupplement">Сохранить</q-btn></q-card-actions></q-card></q-dialog>
    <AppConfirmDialog v-model="deleteDialogVisible" title="Удалить выпускника?" :message="deletingGraduate ? `Будет удалена карточка выпускника: ${studentName(deletingGraduate.student)}.` : 'Будет удалена выбранная карточка выпускника.'" confirm-label="Удалить" tone="negative" @confirm="confirmDelete" />
  </AppPage>
</template>
